import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"定时与主动运行","description":"","frontmatter":{},"headers":[],"relativePath":"智能体设计/定时与主动运行.md","filePath":"智能体设计/定时与主动运行.md","lastUpdated":null}'),h={name:"智能体设计/定时与主动运行.md"};function l(o,t,p,i,n,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="定时与主动运行" tabindex="-1">定时与主动运行 <a class="header-anchor" href="#定时与主动运行" aria-label="Permalink to &quot;定时与主动运行&quot;">​</a></h1><p>智能体不必等下一句对话才工作。到点的任务、周期性的巡检、感知到的现场变化，都可以由运行时主动发起一轮。这三件事的共同点是：唤醒由宿主决定，模型只负责被唤醒后的那一轮。</p><table tabindex="0"><thead><tr><th>唤醒</th><th>触发</th><th>特点</th></tr></thead><tbody><tr><td>到点任务</td><td>调度器扫描发现任务到期</td><td>不调用模型；任务记录在持久存储里</td></tr><tr><td>心跳</td><td>按固定周期发起一轮模型调用</td><td>回答「现在有没有需要人知道的事」</td></tr><tr><td>感知事件</td><td>现场变化变成事件</td><td>走与对话相同的执行路径，不必等用户先说话</td></tr></tbody></table><h2 id="调度器只负责到点" tabindex="-1">调度器只负责到点 <a class="header-anchor" href="#调度器只负责到点" aria-label="Permalink to &quot;调度器只负责到点&quot;">​</a></h2><p>调度器是运行时里的一个周期扫描，不调用模型。它每隔一段时间查看持久存储里哪些任务的下一次执行时间已经到了；没有到期任务时，这一次扫描就是一次查询。提醒不需要亚秒精度，扫描间隔用几十秒这一档就够。</p><p>任务由模型通过工具写入，写入的是数据库里的一条记录，不是模型自己设的一个内存定时器，因此进程重启之后任务还在。模型不能绕过这份记录直接「记住下次提醒」，真正到点把任务跑起来的仍然是调度器。</p><p>一条任务保存：属于哪个会话、要执行的提示、日程类型、日程取值、下一次执行时间、状态（至少进行中、暂停、已完成）。</p><p>日程有三种：</p><table tabindex="0"><thead><tr><th>类型</th><th>取值</th><th>执行后</th></tr></thead><tbody><tr><td>按日历重复</td><td>一条日历表达式，按运行时的时区解释</td><td>算出下一次，状态保持进行中；时区设错，表达式会在错误的钟点触发</td></tr><tr><td>按间隔重复</td><td>一段时长</td><td>从本次执行时刻再推一段，而不是从原来的计划时刻补齐中间每一次</td></tr><tr><td>到点一次</td><td>一个时间点</td><td>标记完成，不再运行</td></tr></tbody></table><p>模型还可以列出、暂停、恢复、取消任务，这些工具只改存储。暂停后再恢复时，按恢复的时刻重算下一次执行时间，避免一恢复就把停机期间积压的那一轮立刻补上。</p><p>多个任务同时到期，串行执行。单次执行设超时：超时后记录失败、释放执行权，并告诉用户这一次没有完成。</p><p>进程停过一段时间再启动时，已过期的任务会在下一次扫描里被看到。一次性提醒应该补跑；按间隔的高频任务如果停机很久会连着补很多次，任务变多之后，改成每个任务只补最近一次。</p><h2 id="心跳不是扫描" tabindex="-1">心跳不是扫描 <a class="header-anchor" href="#心跳不是扫描" aria-label="Permalink to &quot;心跳不是扫描&quot;">​</a></h2><p>到期扫描不调用模型，心跳会。心跳按固定周期发起一轮真正的模型调用，周期通常是几十分钟，并且可以限制在人醒着的时段。它适合「帮我看着某个目录、收件箱或日历，有情况再叫我」；适合放进定时任务的，是「每天某个钟点发一份摘要」「几分钟后提醒一件具体的事」。</p><p>心跳在实现上是一条用户不能删除的内部周期任务，和普通任务共用执行、超时和投递。额外有四条规则：</p><ol><li>使用独立的短会话，不携带日常聊天的长历史；</li><li>清单写短，要求模型严格按清单检查；清单放在工作区的一份短文件里；</li><li>无事时，模型只回复一个约定的标记；宿主看到标记（或去掉标记后所剩无几）就丢掉这轮回复，不发给用户；</li><li>用户对话或定时任务正在跑时，跳过这一拍——心跳排队没有意义，等它排到时，要看的状态已经变了。</li></ol><p>费用主要在每次心跳的模型调用。间隔拉长、限制时段、无事不发，这三件事一起用，心跳才不会变成全天不间断的对话。</p><h2 id="感知也可以开工" tabindex="-1">感知也可以开工 <a class="header-anchor" href="#感知也可以开工" aria-label="Permalink to &quot;感知也可以开工&quot;">​</a></h2><p>现场里的变化是第三种唤醒。有人出现、某人离开、画面里出现需要回应的东西，由感知通道先变成一个事件，运行时用这个事件发起一轮，不必等用户先说话。</p><p>这一轮仍然走进和对话相同的执行路径：装入当前场景允许的身份，走主动问候或迎宾那一条计划，产出要说的话和配套动作，再经通道发出。原始画面留在感知侧，对话提示里只放事件说明。</p><p>感知唤醒要有抑制：同一个人短时间内重复出现，不重复问候；设备处于休眠、正在播报、或已经有一轮对话在进行，这一次感知事件让路或并入当前轮，不另起一轮抢着说话。</p><h2 id="执行时怎么把结果交到人手里" tabindex="-1">执行时怎么把结果交到人手里 <a class="header-anchor" href="#执行时怎么把结果交到人手里" aria-label="Permalink to &quot;执行时怎么把结果交到人手里&quot;">​</a></h2><p>定时任务和心跳的执行，和日常对话有三处不同：</p><table tabindex="0"><thead><tr><th>不同</th><th>规则</th></tr></thead><tbody><tr><td>独立短会话</td><td>不恢复日常聊天的会话标识，也不把这次提示追加进日常档案；任务要记住的内容写在任务提示里，心跳要看的内容写在那份短清单里</td></tr><tr><td>必须能通知用户</td><td>发给执行轮的提示里写明：要用发消息的工具把结果送到这个任务所属的会话，执行轮不把回复只留在模型运行时内部</td></tr><tr><td>忘记发消息时由宿主补发</td><td>宿主记录这一轮有没有调用过发消息；没有调用，就把任务提示或一轮结果用通道直接送出，避免一次成功的执行变成沉默。心跳的无事标记不适用这条补发——无事本来就不该送出</td></tr></tbody></table><p>用户正在对话时，心跳跳过；已经到期的定时任务可以在当前轮结束后串行补上，但要受超时约束。同一时刻仍然只有一轮生成——对话进行中如果让心跳插进来，两轮会抢同一把执行权，也会把巡检回复插进用户正在说的话中间。</p>',25)])])}const c=d(h,[["render",l]]);export{b as __pageData,c as default};
